// 1. Pega a data de hoje (execução)
const hoje = new Date();

// 2. Calcula o mês seguinte (Se hoje for Julho/2026, vai para Agosto/2026)
const proximoMes = new Date(hoje.getFullYear(), hoje.getMonth() + 1, 1);

const ano = proximoMes.getFullYear();
const numeroMes = proximoMes.getMonth() + 1; // 1 a 12
const numeroMesStr = String(numeroMes).padStart(2, '0'); // '08', '09'...

// Nomes dos meses por extenso
const mesesPorExtenso = [
  "JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO",
  "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"
];

const nomeMesMaiusculo = mesesPorExtenso[proximoMes.getMonth()];
const nomeMesMinusculo = nomeMesMaiusculo.toLowerCase();

// 3. Monta as variáveis finais que usaremos no fluxo
const dataPrimeiroDia = `01/${numeroMesStr}/${ano}`;            // Ex: "01/08/2026"
const nomePastaMes = `${numeroMesStr}. ${nomeMesMaiusculo} ${ano}`; // Ex: "08. AGOSTO 2026"
const textoEmpresaMes = `${nomeMesMinusculo} ${ano}`;            // Ex: "agosto 2026"

// Retorna o objeto completo para os próximos nós
return [{
  json: {
    data_primeiro_dia: dataPrimeiroDia,
    nome_pasta_mes: nomePastaMes,
    texto_empresa_mes: textoEmpresaMes,
    ano_vigente: ano,
    mes_num: numeroMes
  }
}];

// Pega o ID da planilha e os dados da data do mês anterior
const idPlanilha = $('Trás o ID do sheets recem criado').first().json.id_sheets_escala_recem_criada;
const dadosMesQueVem = $('Calcula a data do mês que vem').first().json;

let ano, mes;
if (dadosMesQueVem.ano && dadosMesQueVem.mes) {
  ano = Number(dadosMesQueVem.ano);
  mes = Number(dadosMesQueVem.mes);
} else if (dadosMesQueVem.nome_pasta_mes) {
  const partes = dadosMesQueVem.nome_pasta_mes.split(' ');
  mes = parseInt(partes[0].replace('.', ''), 10);
  ano = parseInt(partes[2], 10);
} else {
  const hoje = new Date();
  const proximoMesDate = new Date(hoje.getFullYear(), hoje.getMonth() + 1, 1);
  ano = proximoMesDate.getFullYear();
  mes = proximoMesDate.getMonth() + 1;
}

// 1. Data do dia 1 do mês
const primeiroDiaDoMes = new Date(ano, mes - 1, 1);

// 2. Descobre o dia da semana do dia 1 (0 = Domingo, 1 = Segunda, ..., 6 = Sábado)
const diaDaSemana = primeiroDiaDoMes.getDay();

// 3. Volta os dias até achar o Domingo anterior ou o próprio Domingo
const primeiroDomingo = new Date(primeiroDiaDoMes);
primeiroDomingo.setDate(primeiroDiaDoMes.getDate() - diaDaSemana);

// 4. Formata para DD/MM/YYYY
const diaF = String(primeiroDomingo.getDate()).padStart(2, '0');
const mesF = String(primeiroDomingo.getMonth() + 1).padStart(2, '0');
const anoF = primeiroDomingo.getFullYear();

const dataInicialImpressao = `${diaF}/${mesF}/${anoF}`;

return [{
  json: {
    id_sheets_escala_recem_criada: idPlanilha,
    data_inicial_impressao: dataInicialImpressao
  }
}];

const idPlanilha = $('Trás o ID do sheets recem criado').first().json.id_sheets_escala_recem_criada;
const dadosMesQueVem = $('Calcula a data do mês que vem').first().json;

let ano, mes;
if (dadosMesQueVem.ano && dadosMesQueVem.mes) {
  ano = Number(dadosMesQueVem.ano);
  mes = Number(dadosMesQueVem.mes);
} else if (dadosMesQueVem.nome_pasta_mes) {
  const partes = dadosMesQueVem.nome_pasta_mes.split(' ');
  mes = parseInt(partes[0].replace('.', ''), 10);
  ano = parseInt(partes[2], 10);
} else {
  const hoje = new Date();
  const proximoMesDate = new Date(hoje.getFullYear(), hoje.getMonth() + 1, 1);
  ano = proximoMesDate.getFullYear();
  mes = proximoMesDate.getMonth() + 1;
}

const primeiroDiaDoMes = new Date(ano, mes - 1, 1);
const ultimoDiaDoMes = new Date(ano, mes, 0);

// Encontra o domingo inicial da primeira semana
let dataAtual = new Date(primeiroDiaDoMes);
dataAtual.setDate(dataAtual.getDate() - dataAtual.getDay());

const mapaDias = {
  0: 'Atende domingo?', 1: 'Atende segunda?', 2: 'Atende terça?',
  3: 'Atende quarta?', 4: 'Atende quinta?', 5: 'Atende sexta?', 6: 'Atende sabado?'
};

// Busca os médicos direto do nó correto
const medicos = $('Trás as escalas de todos os médicos').all().map(item => item.json);
const matrizImpressao = [];

// Roda até construir todas as semanas do mês alvo
while (dataAtual <= ultimoDiaDoMes) {
  let linhaDatas = [];
  let datasDaSemana = [];

  // 1. Cabeçalho de datas da semana (Ex: 26/07)
  for (let i = 0; i < 7; i++) {
    let diaF = String(dataAtual.getDate()).padStart(2, '0');
    let mesF = String(dataAtual.getMonth() + 1).padStart(2, '0');
    linhaDatas.push(`${diaF}/${mesF}`);
    datasDaSemana.push(new Date(dataAtual));
    dataAtual.setDate(dataAtual.getDate() + 1); // Avança 1 dia
  }
  matrizImpressao.push(linhaDatas); 

  // 2. Coleta os médicos agrupando POR DIA (empacotamento eficiente)
  let colunasDaSemana = [[], [], [], [], [], [], []];

  for (let i = 0; i < 7; i++) {
    let dataDia = datasDaSemana[i];
    let diaSemanaNum = dataDia.getDay();
    let colunaAtende = mapaDias[diaSemanaNum];

    // É do mês alvo?
    if (dataDia.getMonth() + 1 === mes) {
      medicos.forEach(medico => {
        if (medico[colunaAtende] && medico[colunaAtende].toString().trim().toLowerCase() === 'sim') {
          let nome = medico['Nome do Profissional'] || '';
          let inicio = medico['Horário Início'] || '';
          let fim = medico['Horário Fim'] || '';
          let vagas = medico['Qtd Vagas'] || '';
          let tipoAtendimento = medico['Tipo Atendimento'] || 'Consulta';

          colunasDaSemana[i].push(`${nome}\n(${vagas}) ${inicio} - ${fim}\n${tipoAtendimento}`);
        }
      });
    }
  }

  // 3. Monta as 5 linhas da semana pegando as células certas de cada coluna
  for (let rowIndex = 0; rowIndex < 5; rowIndex++) {
    let linha = [];
    for (let dayIndex = 0; dayIndex < 7; dayIndex++) {
      // Pega o médico na posição (rowIndex) daquele dia. Se não tiver, deixa vazio ""
      linha.push(colunasDaSemana[dayIndex][rowIndex] || "");
    }
    matrizImpressao.push(linha);
  }
}

return [{
  json: {
    id_sheets_escala_recem_criada: idPlanilha,
    values_impressao: matrizImpressao
  }
}];

