let matrizLinhas = [];
const anoRef = 2026;
const mesRef = 9; // Setembro

function gerarSemanaDinamica(dataInicioStr) {
  let [diaI, mesI, anoI] = dataInicioStr.split('.').map(Number);
  let dataAtual = new Date(anoI, mesI - 1, diaI);

  let arrayDatas = [];
  const diasSemanaNomes = ["SEGUNDA", "TERÇA", "QUARTA", "QUINTA", "SEXTA", "SÁBADO", "DOMINGO"];

  // 1. Monta a linha de título/data (Colunas A a G)
  for (let i = 0; i < 7; i++) {
    let d = new Date(dataAtual);
    d.setDate(dataAtual.getDate() + i);

    let dDia = String(d.getDate()).padStart(2, '0');
    let dMes = String(d.getMonth() + 1).padStart(2, '0');
    let dAno = d.getFullYear();

    if (d.getMonth() + 1 === mesRef && d.getFullYear() === anoRef) {
      arrayDatas.push(`${diasSemanaNomes[i]} ${dDia}.${dMes}.${dAno}`);
    } else {
      arrayDatas.push("");
    }
  }

  // Variável para contar o total de escalas (médicos) nesta semana específica
  let totalEscalasSemana = 0;
  let linhasTemporariasMedicos = [];

  // 2. Preenche as 6 linhas de médicos
  for (let linha = 0; linha < 6; linha++) {
    let linhaCols = [];
    for (let i = 0; i < 7; i++) {
      let d = new Date(dataAtual);
      d.setDate(dataAtual.getDate() + i);

      if (d.getMonth() + 1 === mesRef && d.getFullYear() === anoRef) {
        let diaSemanaIndex = i;
        let valorCel = "";

        if (diaSemanaIndex === 0) valorCel = escalasPorDia.Segunda[linha] || "";
        else if (diaSemanaIndex === 1) valorCel = escalasPorDia.Terca[linha] || "";
        else if (diaSemanaIndex === 2) valorCel = escalasPorDia.Quarta[linha] || "";
        else if (diaSemanaIndex === 3) valorCel = escalasPorDia.Quinta[linha] || "";
        else if (diaSemanaIndex === 4) valorCel = escalasPorDia.Sexta[linha] || "";

        if (valorCel !== "") {
          totalEscalasSemana++;
        }
        linhaCols.push(valorCel);
      } else {
        linhaCols.push("");
      }
    }
    linhasTemporariasMedicos.push(linhaCols);
  }

  // 3. Adiciona a coluna H na linha de data (índice 0 da semana): Total de Vagas da Semana (Escalas * 30)
  arrayDatas.push(totalEscalasSemana * 30);
  matrizLinhas.push(arrayDatas);

  // 4. Adiciona as 6 linhas de médicos na matriz (com a coluna H vazia nessas 6 linhas)
  linhasTemporariasMedicos.forEach(linhaCols => {
    linhaCols.push(""); // Coluna H vazia nas linhas de médicos
    matrizLinhas.push(linhaCols);
  });
}

// Gera as 5 semanas do mês dinamicamente
gerarSemanaDinamica("31.08.2026"); // Semana 1 (H16)
gerarSemanaDinamica("07.09.2026"); // Semana 2 (H23)
gerarSemanaDinamica("14.09.2026"); // Semana 3 (H30)
gerarSemanaDinamica("21.09.2026"); // Semana 4 (H37)
gerarSemanaDinamica("28.09.2026"); // Semana 5 (H44)

return [{
  json: {
    tabelaCompletaStr: JSON.stringify(matrizLinhas)
  }
}];

